begin;
select no_plan();
select has_table('public','baseline_progress','resumable operator progress exists');
select has_table('public','baseline_snapshots','dated baselines exist');
select has_function('public','save_baseline_progress',array['uuid','bigint','text','uuid','uuid','boolean'],'guarded save exists');
select ok(not has_function_privilege('anon','public.save_baseline_progress(uuid,bigint,text,uuid,uuid,boolean)','EXECUTE'),'anonymous RPC execution denied');
select ok(not has_function_privilege('service_role','public.save_baseline_progress(uuid,bigint,text,uuid,uuid,boolean)','EXECUTE'),'service worker RPC execution denied');
select ok(not has_table_privilege(r, 'public.'||t, p), r||' denied '||p||' on '||t)
from unnest(array['anon','authenticated','service_role']) r cross join unnest(array['baseline_progress','baseline_snapshots']) t cross join unnest(array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)
select ('98000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','baseline-'||n||'@example.test','',now(),'{}','{}' from generate_series(1,4) n;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.org',public.create_organisation_with_owner('Baseline A','baseline-a')::text,true);
insert into public.memberships(organisation_id,user_id,role) values(current_setting('test.org')::uuid,'98000000-0000-4000-8000-000000000002','member'),(current_setting('test.org')::uuid,'98000000-0000-4000-8000-000000000003','admin');
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select set_config('test.other',public.create_organisation_with_owner('Baseline B','baseline-b')::text,true);
reset role;
insert into public.catalogue_versions(id,version,title,published_at) values('98000000-0000-4000-8000-000000000101','baseline-test-v1','Fixture',now());
insert into public.catalogue_categories(id,catalogue_version_id,code,title,position) values('98000000-0000-4000-8000-000000000102','98000000-0000-4000-8000-000000000101','B','Baseline',0);
insert into public.catalogue_questions(id,catalogue_version_id,category_id,code,prompt,position) values('98000000-0000-4000-8000-000000000103','98000000-0000-4000-8000-000000000101','98000000-0000-4000-8000-000000000102','B1','Restore tested?',0);
insert into public.assessment_sessions(id,organisation_id,catalogue_version_id,title,created_by) values
('98000000-0000-4000-8000-000000000104',current_setting('test.org')::uuid,'98000000-0000-4000-8000-000000000101','Partial readiness','98000000-0000-4000-8000-000000000001'),
('98000000-0000-4000-8000-000000000105',current_setting('test.other')::uuid,'98000000-0000-4000-8000-000000000101','Other tenant','98000000-0000-4000-8000-000000000004');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.organisation_scope_profiles(organisation_id,scope_statement,updated_by) values(current_setting('test.org')::uuid,'Original boundary','98000000-0000-4000-8000-000000000001');
insert into public.evidence(id,organisation_id,title,kind,valid_until,created_by) values('98000000-0000-4000-8000-000000000106',current_setting('test.org')::uuid,'Expired proof','note',current_date-1,'98000000-0000-4000-8000-000000000001');
insert into public.evidence(organisation_id,title,kind,status,created_by) values(current_setting('test.org')::uuid,'Explicitly stale proof','note','expired','98000000-0000-4000-8000-000000000001');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,'Objective','98000000-0000-4000-8000-000000000105','98000000-0000-4000-8000-000000000201',false)$$,'42501','assessment not found in workspace','cross-tenant assessment denied');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,E'\t\n',null,'98000000-0000-4000-8000-000000000201',false)$$,'22023','invalid baseline input','blank objective rejected');
reset role;
alter table public.baseline_snapshots add constraint test_snapshot_atomicity check (payload->>'objective' <> 'Forced failure');
set local role authenticated;
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,'Forced failure',null,'98000000-0000-4000-8000-000000000299',true)$$,'23514',null,'snapshot failure rejects entire save');
select is((select count(*) from public.baseline_progress where organisation_id=current_setting('test.org')::uuid),0::bigint,'failed snapshot leaves no progress edit');
reset role;
alter table public.baseline_snapshots drop constraint test_snapshot_atomicity;
set local role authenticated;
select set_config('test.draft',public.save_baseline_progress(current_setting('test.org')::uuid,0,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000201',false)::text,true);
select is((current_setting('test.draft')::jsonb->>'revision'),'1','draft revision saved');
select is(public.save_baseline_progress(current_setting('test.org')::uuid,0,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000201',false)::text,current_setting('test.draft'),'immediate draft retry returns same revision');
select is((select objective from public.baseline_progress where organisation_id=current_setting('test.org')::uuid),'Start readiness','draft resumes saved objective');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,'Other',null,'98000000-0000-4000-8000-000000000202',false)$$,'PT409','baseline revision changed; reload before saving','stale draft cannot overwrite');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,'Changed',null,'98000000-0000-4000-8000-000000000201',false)$$,'22023','request id already used with different baseline input','changed retry rejected');
select set_config('test.saved',public.save_baseline_progress(current_setting('test.org')::uuid,1,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000202',true)::text,true);
select set_config('test.snapshot',(current_setting('test.saved')::jsonb->>'snapshot_id'),true);
select set_config('test.payload',(select payload::text from public.baseline_snapshots where id=current_setting('test.snapshot')::uuid),true);
select is((current_setting('test.payload')::jsonb#>>'{scope,scope_statement}'),'Original boundary','saved historic scope');
select is(jsonb_array_length(current_setting('test.payload')::jsonb->'questions'),1,'unanswered catalogue question captured');
select is(current_setting('test.payload')::jsonb#>>'{questions,0,answer}',null,'unanswered stays unanswered');
select is(current_setting('test.payload')::jsonb#>>'{counts,expiredEvidence}','2','expiry respects explicit stale status and elapsed date');
select is(current_setting('test.payload')::jsonb#>>'{counts,scopeGaps}','5','all six scope fields determine completeness');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,0,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000201',false)$$,'PT409','baseline revision changed; reload before saving','old progress retry after newer edit fails stale');
update public.organisation_scope_profiles set scope_statement='New boundary' where organisation_id=current_setting('test.org')::uuid;
select lives_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,2,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000203',true)$$,'intentional save creates successor');
select is(public.save_baseline_progress(current_setting('test.org')::uuid,1,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000202',true)::text,current_setting('test.saved'),'old snapshot retry permanently returns original result');
select is((select revision from public.baseline_progress where organisation_id=current_setting('test.org')::uuid),3::bigint,'old snapshot replay does not roll back draft');
select is((select count(*) from public.baseline_snapshots where organisation_id=current_setting('test.org')::uuid),2::bigint,'snapshot retry creates no duplicate');
select is((select payload::text from public.baseline_snapshots where id=current_setting('test.snapshot')::uuid),current_setting('test.payload'),'source change leaves entire historic payload unchanged');
select throws_ok($$update public.baseline_snapshots set payload='{}'$$,'42501',null,'operators cannot directly rewrite snapshots');
select throws_ok($$delete from public.baseline_snapshots$$,'42501',null,'operators cannot delete snapshots');
select throws_ok($$insert into public.baseline_progress(organisation_id) values(current_setting('test.org')::uuid)$$,'42501',null,'operators cannot bypass draft RPC');
reset role;
select throws_ok($$update public.baseline_snapshots set payload='{}'$$,'P0001','baseline snapshots are immutable','privileged snapshot rewrite rejected');
select throws_ok($$delete from public.baseline_snapshots$$,'P0001','baseline snapshots are immutable','privileged snapshot deletion rejected');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.baseline_snapshots),2::bigint,'member reads saved workspace baselines');
select is((select count(*) from public.baseline_progress),0::bigint,'member does not read unsaved coordinator progress');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,3,'No',null,'98000000-0000-4000-8000-000000000204',true)$$,'42501','current workspace operator required','member save denied');
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.baseline_snapshots),0::bigint,'other tenant sees no snapshots');
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,1,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000202',true)$$,'42501','current workspace operator required','cross-tenant snapshot retry denied');
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,1,'Start readiness','98000000-0000-4000-8000-000000000104','98000000-0000-4000-8000-000000000202',true)$$,'22023','request id already used with different baseline input','different actor cannot reuse snapshot request identity');
select lives_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,3,'Admin edit',null,'98000000-0000-4000-8000-000000000205',true)$$,'admin coordinator may save');
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update public.memberships set role='member' where organisation_id=current_setting('test.org')::uuid and user_id='98000000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,3,'Admin edit',null,'98000000-0000-4000-8000-000000000205',true)$$,'42501','current workspace operator required','demoted operator cannot replay save');
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
delete from public.memberships where organisation_id=current_setting('test.org')::uuid and user_id='98000000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.save_baseline_progress(current_setting('test.org')::uuid,3,'Admin edit',null,'98000000-0000-4000-8000-000000000205',true)$$,'42501','current workspace operator required','removed operator cannot replay save');
select is((select count(*) from public.baseline_snapshots),0::bigint,'removed operator cannot read saved snapshots');
select * from finish();
rollback;
